    # Merge windows union first.
    merged = []
    for start, end in sorted(intervals):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            if end > merged[-1][1]:
                merged[-1][1] = end

    # Subtract busy intervals.
    free = []
    for start, end in merged:
        cur = start
        for bs, be in sorted(busy_intervals):
