import json
import math
from pathlib import Path


def _reject_nonfinite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
        return
    if isinstance(obj, list):
        for item in obj:
            _reject_nonfinite(item)
        return
    if isinstance(obj, dict):
        for value in obj.values():
            _reject_nonfinite(value)
        return


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=lambda c: (_ for _ in ()).throw(ValueError("non-standard JSON number")))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("invalid JSON") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _reject_nonfinite(data)
    return data

def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    slots_payload = _unwrap(payloads[0])
    invitees_payload = _unwrap(payloads[1])
    supplies_payload = _unwrap(payloads[2])

    if not isinstance(slots_payload, dict):
        raise ValueError("slots must be object")
    if not isinstance(invitees_payload, dict):
        raise ValueError("invitees must be object")
    if not isinstance(supplies_payload, dict):
        raise ValueError("supplies must be object")

    slots = slots_payload.get("slots")
    complete = slots_payload.get("complete")
    if not isinstance(slots, list):
        raise ValueError("slots must be list")
    if not isinstance(complete, bool):
        raise ValueError("complete must be bool")

    members = invitees_payload.get("members")
    group_id = invitees_payload.get("group_id")
    if not isinstance(members, list):
        raise ValueError("members must be list")
    if not isinstance(group_id, str) or not group_id.strip():
        raise ValueError("group_id must be non-empty string")

    purchase = supplies_payload

    events = []
    notification = None
    if complete:
        if len(slots) < 2:
            raise ValueError("complete requires two slots")
        for i, slot in enumerate(slots[:2]):
            if not isinstance(slot, dict):
                raise ValueError("slot must be object")
            start = slot.get("start")
            end = slot.get("end")
            if not isinstance(start, int) or isinstance(start, bool):
                raise ValueError("slot start must be int")
            if not isinstance(end, int) or isinstance(end, bool):
                raise ValueError("slot end must be int")
            events.append({
                "id": group_id + "-" + str(i + 1),
                "start": start,
                "end": end,
                "members": list(members),
            })
        notification = {
            "group_id": group_id,
            "members": list(members),
            "event_ids": [e["id"] for e in events],
        }

    return {
        "name": contract["name"],
        "result": {
            "events": events,
            "notification": notification,
            "purchase": purchase,
        },
    }

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def main():
    contracts = sorted(
        p for p in ROOT.rglob("contract.json")
        if "outputs" not in p.relative_to(ROOT).parts
    )
    if not contracts:
        raise ValueError("no contracts")

    # Topological order by dependency: a component depends on another if its
    # input path equals the other's output path.
    by_name = {}
    for cp in contracts:
        c = json.loads(cp.read_text(encoding="utf-8"))
        by_name[c["name"]] = (cp, c)

    deps = {}
    for name, (cp, c) in by_name.items():
        d = set()
        for inp in c["inputs"]:
            for other_name, (ocp, oc) in by_name.items():
                if other_name != name and inp == oc["output"]:
                    d.add(other_name)
        deps[name] = d

    # Detect cycles.
    order = []
    remaining = set(by_name)
    while remaining:
        ready = [n for n in remaining if deps[n] <= set(order)]
        if not ready:
            raise ValueError("dependency cycle detected")
        ready.sort()
        for n in ready:
            remaining.remove(n)
            order.append(n)

    for name in order:
        cp, c = by_name[name]
        subprocess.run(
            [sys.executable, str(cp.with_name("render.py"))],
            cwd=ROOT,
            check=True,
        )

    subprocess.run(
        [sys.executable, str(ROOT / "integrate.py")],
        cwd=ROOT,
        check=True,
    )

    subprocess.run(
        [sys.executable, str(ROOT / "final_report.py")],
        cwd=ROOT,
        check=True,
    )


if __name__ == "__main__":
    main()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _attention(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.append(name)
            continue
        for key in ("complete", "checkout", "committed", "ok"):
            if result.get(key) is False:
                names.append(name)
                break
        else:
            for key in ("unavailable", "missing", "conflicts", "unreachable"):
                v = result.get(key)
                if isinstance(v, (list, dict, str, tuple)) and len(v) > 0:
                    names.append(name)
                    break
    return sorted(set(names))


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"))
    components = core["components"]

    serialized = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(serialized).hexdigest()

    report = {
        "title": "两场座谈会、群邀请与物资采购",
        "component_count": len(components),
        "sha256": sha256,
        "attention": _attention(components),
    }

    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

